// Renders **bold** segments without injecting HTML.
const renderEmphasis = (text) =>
  text.split("**").map((part, i) => (i % 2 ? <strong key={i}>{part}</strong> : part));

const currency = (n) =>
  `\u20B1${n.toLocaleString("en-PH", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

// Readable height for the unit warnings: tiny values keep their significant digits.
// Plain numeric strings only, because it also feeds a type="number" input.
const formatCm = (n) => (n < 1 ? String(Number(n.toPrecision(2))) : n.toFixed(1));

// Copies text and returns a promise, so callers handle "no clipboard" the same as a refusal.
function copyToClipboard(text) {
  try {
    return navigator.clipboard.writeText(text);
  } catch (e) {
    return Promise.reject(e);
  }
}

// True when the page is open inside another app's built-in browser (Facebook, Instagram,
// TikTok, ...) or as an installed home-screen app. Those can't use the visitor's Messenger
// login, so Messenger can open logged out. It can't see every case: an "app popup" such as
// a Chrome Custom Tab looks exactly like the normal browser, which is why phones never jump
// to Messenger automatically (see shouldAutoOpenMessenger).
function detectEmbeddedBrowser() {
  if (typeof window === "undefined" || typeof navigator === "undefined") return false;
  const ua = navigator.userAgent || "";
  const standalone =
    window.matchMedia?.("(display-mode: standalone)")?.matches || navigator.standalone === true;
  const knownApps =
    /FBAN|FBAV|FB_IAB|Instagram|TikTok|musical_ly|BytedanceWebview|Snapchat|Line\/|KAKAOTALK|MicroMessenger|Twitter|Pinterest|LinkedInApp|GSA\//i;
  const androidWebView = /; wv\)/.test(ua);
  const iosWebView = /iPhone|iPad|iPod/.test(ua) && !/Safari\//.test(ua); // web views drop "Safari/"
  return Boolean(standalone || knownApps.test(ua) || androidWebView || iosWebView);
}

// Only desktop browsers open Messenger straight from the Submit tap. On a phone the page may
// be in a viewer without the customer's login, so it shows steps and an "Open Messenger chat"
// link instead.
function shouldAutoOpenMessenger() {
  if (typeof window === "undefined") return false;
  const touch = window.matchMedia?.("(pointer: coarse)")?.matches;
  return !touch && !detectEmbeddedBrowser();
}

/* ---------------------------------------------------------
   MESH PARSING (STL + OBJ). Pure functions, no dependencies.
   Returns { volumeCm3, dimsCm: {x,y,z} } assuming the file's
   native units are millimeters, the near-universal convention
   for STL/OBJ exported by slicers and most 3D tools.
--------------------------------------------------------- */

function signedTriVolume(v1, v2, v3) {
  return (
    (v1.x * (v2.y * v3.z - v3.y * v2.z) -
      v1.y * (v2.x * v3.z - v3.x * v2.z) +
      v1.z * (v2.x * v3.y - v3.x * v2.y)) /
    6.0
  );
}

function boundsFromExtent(min, max) {
  return {
    x: (max.x - min.x) / 10, // mm -> cm
    y: (max.y - min.y) / 10,
    z: (max.z - min.z) / 10,
  };
}

function measureMesh(triangles) {
  let volume = 0;
  const min = { x: Infinity, y: Infinity, z: Infinity };
  const max = { x: -Infinity, y: -Infinity, z: -Infinity };

  for (const [v1, v2, v3] of triangles) {
    volume += signedTriVolume(v1, v2, v3);
    for (const v of [v1, v2, v3]) {
      min.x = Math.min(min.x, v.x); max.x = Math.max(max.x, v.x);
      min.y = Math.min(min.y, v.y); max.y = Math.max(max.y, v.y);
      min.z = Math.min(min.z, v.z); max.z = Math.max(max.z, v.z);
    }
  }

  if (!triangles.length || !isFinite(min.x)) {
    throw new Error("No triangles found in file.");
  }

  const volumeMm3 = Math.abs(volume);
  return {
    volumeCm3: volumeMm3 / 1000,
    dimsCm: boundsFromExtent(min, max),
  };
}

function parseSTL(buffer) {
  const dv = new DataView(buffer);
  const triCountFromHeader = buffer.byteLength >= 84 ? dv.getUint32(80, true) : 0;
  const expectedBinarySize = 84 + triCountFromHeader * 50;
  // Some exporters pad the end of a binary STL, so "at least" the expected size is enough.
  // An ASCII file can't pass this: its first bytes read as a triangle count far larger than
  // the file could hold.
  const isBinary = triCountFromHeader > 0 && buffer.byteLength >= expectedBinarySize;

  const triangles = [];

  if (isBinary) {
    let offset = 84;
    for (let i = 0; i < triCountFromHeader; i++) {
      offset += 12; // skip normal
      const verts = [];
      for (let v = 0; v < 3; v++) {
        verts.push({
          x: dv.getFloat32(offset, true),
          y: dv.getFloat32(offset + 4, true),
          z: dv.getFloat32(offset + 8, true),
        });
        offset += 12;
      }
      offset += 2; // skip attribute byte count
      triangles.push(verts);
    }
  } else {
    const text = new TextDecoder().decode(buffer);
    const vertexRegex = /vertex\s+([-\d.eE+]+)\s+([-\d.eE+]+)\s+([-\d.eE+]+)/g;
    let match;
    let current = [];
    while ((match = vertexRegex.exec(text)) !== null) {
      current.push({
        x: parseFloat(match[1]),
        y: parseFloat(match[2]),
        z: parseFloat(match[3]),
      });
      if (current.length === 3) {
        triangles.push(current);
        current = [];
      }
    }
  }

  return measureMesh(triangles);
}

function parseOBJ(text) {
  const vertices = [];
  const triangles = [];

  const lines = text.split("\n");
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed.startsWith("v ")) {
      const parts = trimmed.split(/\s+/);
      vertices.push({
        x: parseFloat(parts[1]),
        y: parseFloat(parts[2]),
        z: parseFloat(parts[3]),
      });
    } else if (trimmed.startsWith("f ")) {
      const parts = trimmed.split(/\s+/).slice(1);
      const idxs = parts.map((p) => {
        let i = parseInt(p.split("/")[0], 10);
        if (i < 0) i = vertices.length + i + 1;
        return i - 1;
      });
      for (let i = 1; i < idxs.length - 1; i++) {
        const a = vertices[idxs[0]];
        const b = vertices[idxs[i]];
        const c = vertices[idxs[i + 1]];
        if (a && b && c) triangles.push([a, b, c]);
      }
    }
  }

  return measureMesh(triangles);
}

// Pull filament usage out of a sliced G-code header/footer. Returns cm3 of
// filament extruded (supports and infill included), or null if not found.
function extractGcodeVolumeCm3(text) {
  const nums = (str) =>
    str
      .split(/[,\s]+/)
      .map((n) => parseFloat(n))
      .filter((n) => isFinite(n));
  const sum = (arr) => arr.reduce((a, b) => a + b, 0);

  const dMatch = text.match(/;\s*filament_diameter\s*[:=]\s*([\d.]+)/i);
  const diameter = dMatch ? parseFloat(dMatch[1]) : 1.75;
  const areaMm2 = Math.PI * Math.pow(diameter / 2, 2);

  // 1. Volume in cm3 (Bambu Studio / Orca "total filament volume", PrusaSlicer "filament used [cm3]")
  let m = text.match(/;\s*(?:total )?filament (?:used|volume)\s*\[cm\^?3\]\s*[:=]\s*([ \t\d.,]+)/i);
  if (m && sum(nums(m[1])) > 0) return sum(nums(m[1]));

  // 2. Length in mm, converted with the filament diameter
  m = text.match(/;\s*(?:total )?filament (?:used|length)\s*\[mm\]\s*[:=]\s*([ \t\d.,]+)/i);
  if (m && sum(nums(m[1])) > 0) return (sum(nums(m[1])) * areaMm2) / 1000;

  // 3. Cura style, length in meters
  m = text.match(/;\s*Filament used:\s*([ \t\d.,m]+)/i);
  if (m && sum(nums(m[1].replace(/m/gi, ""))) > 0) {
    return (sum(nums(m[1].replace(/m/gi, ""))) * 1000 * areaMm2) / 1000;
  }

  return null;
}

async function parseGcode(file) {
  // Slicers write the summary near the top or the bottom, so only read both ends.
  const CHUNK = 400 * 1024;
  let text = await file.slice(0, CHUNK).text();
  if (file.size > CHUNK) {
    text += "\n" + (await file.slice(Math.max(CHUNK, file.size - CHUNK)).text());
  }
  const vol = extractGcodeVolumeCm3(text);
  if (vol == null) throw new Error("Couldn't find filament usage in this G-code.");
  return vol;
}

async function parseFile(file) {
  const name = file.name.toLowerCase();
  if (/\.stl$/.test(name)) return { kind: "mesh", ...parseSTL(await file.arrayBuffer()) };
  if (/\.obj$/.test(name)) return { kind: "mesh", ...parseOBJ(await file.text()) };
  if (/\.(gcode|gco|gc)$/.test(name)) return { kind: "gcode", volumeCm3: await parseGcode(file) };
  if (/\.3mf$/.test(name)) throw new Error("Export a plain .gcode file, not .3mf.");
  throw new Error("Unsupported file type.");
}

/* ---------------------------------------------------------
   STATE
--------------------------------------------------------- */
const initialState = {
  path: "upload", // 'upload' | 'category'
  files: [], // { id, name, size, status: 'parsing'|'done'|'error', kind, volumeCm3, dimsCm, error }
  // null means "use the auto value from the files". An empty string means the person has
  // cleared the box to retype, so it must not snap back to the estimate mid-edit.
  weightOverride: null,
  heightOverride: null,
  category: null,
  material: "PLA",
  strength: "Standard",
  addons: { priming: false, rush: false, paint: "none" }, // paint: 'none' | 'flat' | 'simple' | 'detailed'
};

function reducer(state, action) {
  switch (action.type) {
    case "SET_PATH":
      return { ...state, path: action.value, category: null };
    case "ADD_FILES":
      return {
        ...state,
        files: [...state.files, ...action.entries],
        weightOverride: null,
        heightOverride: null,
      };
    case "FILE_RESULT":
      return {
        ...state,
        files: state.files.map((f) =>
          f.id === action.id ? { ...f, ...action.result, status: "done" } : f
        ),
      };
    case "FILE_ERROR":
      return {
        ...state,
        files: state.files.map((f) =>
          f.id === action.id ? { ...f, status: "error", error: action.message } : f
        ),
      };
    case "REMOVE_FILE":
      return {
        ...state,
        files: state.files.filter((f) => f.id !== action.id),
        weightOverride: null,
        heightOverride: null,
      };
    case "SET_FIELD":
      return { ...state, [action.field]: action.value };
    case "SET_CATEGORY":
      return { ...state, category: action.value };
    case "SET_MATERIAL":
      return { ...state, material: action.value };
    case "SET_STRENGTH":
      return { ...state, strength: action.value };
    case "TOGGLE_ADDON":
      return {
        ...state,
        addons: { ...state.addons, [action.value]: !state.addons[action.value] },
      };
    case "SET_PAINT":
      return { ...state, addons: { ...state.addons, paint: action.value } };
    case "RESET":
      return initialState;
    default:
      return state;
  }
}

/* ---------------------------------------------------------
   PRICE CALC (pure function, easy to unit test/reuse)
--------------------------------------------------------- */
function calculatePrice(state) {
  const strength = STRENGTH_PROFILES[state.strength];
  const material = MATERIALS[state.material];

  let weight = 0;
  let adjWeight = 0;
  let autoMeshGrams = 0;
  let gcodeGrams = 0;
  let supportGrams = 0;
  let tallestCm = 0;
  let unitsSuspect = false;
  let smallModelHint = false;
  let needsManualWeight = false;

  if (state.path === "upload") {
    const done = state.files.filter((f) => f.status === "done");
    const meshFiles = done.filter((f) => f.kind === "mesh");
    const gcodeFiles = done.filter((f) => f.kind === "gcode");

    // Solid weight of all STL/OBJ pieces combined, then scaled by the strength profile.
    autoMeshGrams = meshFiles.reduce((t, f) => t + f.volumeCm3, 0) * material.density;
    // G-code is already sliced: filament volume x density, used as-is.
    gcodeGrams = gcodeFiles.reduce((t, f) => t + f.volumeCm3, 0) * material.density;
    tallestCm = Math.max(0, ...meshFiles.map((f) => Math.max(f.dimsCm.x, f.dimsCm.y, f.dimsCm.z)));

    unitsSuspect =
      meshFiles.length > 0 && (tallestCm < SANE_TALLEST_CM.min || tallestCm > SANE_TALLEST_CM.max);
    smallModelHint = meshFiles.length > 0 && !unitsSuspect && tallestCm < SMALL_MODEL_HINT_CM;

    // A file with a suspicious size can't be trusted for weight, so it only quotes once a
    // weight has been typed in.
    const meshGrams =
      state.weightOverride !== null
        ? parseFloat(state.weightOverride) || 0
        : unitsSuspect
        ? 0
        : autoMeshGrams;
    needsManualWeight = unitsSuspect && meshGrams <= 0;
    const meshAdj = meshGrams * strength.multiplier;
    supportGrams = meshAdj * SUPPORT_ALLOWANCE;

    weight = meshGrams + gcodeGrams;
    adjWeight = meshAdj + supportGrams + gcodeGrams;
  } else {
    weight = presetWeight(state.category, state.material);
    adjWeight = weight * strength.multiplier;
  }

  const materialCost = adjWeight * material.costPerGram;
  const estHours = material.gramsPerHour > 0 ? adjWeight / material.gramsPerHour : 0;
  const laborCost = estHours * LABOR_RATE_PER_HOUR;
  const subtotal = materialCost + laborCost;

  // Paint price for this piece, rounded to the nearest 10 so the buttons read cleanly.
  // Below the base weight it never drops under the listed price.
  const paintWeightPla = (weight * MATERIALS.PLA.density) / material.density;
  const paintScale = Math.max(1, paintWeightPla / PAINT_BASE_GRAMS);
  const scalePaint = (base) => Math.round((base * paintScale) / 10) * 10;
  const paintPrices = {
    flat: scalePaint(ADDON_PRICES.paintFlat),
    simple: scalePaint(ADDON_PRICES.paintSimple),
    detailed: scalePaint(ADDON_PRICES.paintDetailed),
  };

  const primingFee = state.addons.priming ? ADDON_PRICES.priming : 0;
  const paintFee = paintPrices[state.addons.paint] || 0; // "none" has no price
  const addonsTotal = primingFee + paintFee;

  const rushSurcharge = state.addons.rush ? (subtotal + addonsTotal) * RUSH_MULTIPLIER : 0;
  const total = subtotal + addonsTotal + rushSurcharge;

  return {
    weight,
    adjWeight,
    autoMeshGrams,
    gcodeGrams,
    supportGrams,
    tallestCm,
    unitsSuspect,
    smallModelHint,
    needsManualWeight,
    materialCost,
    laborCost,
    estHours,
    subtotal,
    addonsTotal,
    primingFee,
    paintFee,
    paintPrices,
    rushSurcharge,
    total,
    ready: adjWeight > 0 && !needsManualWeight,
  };
}

function quoteSummaryText(state, price, agreed) {
  const lines = [];
  lines.push("Cosplay print quote request:");
  if (state.path === "upload" && state.files.length > 0) {
    lines.push(`Files: ${state.files.map((f) => f.name).join(", ")}`);
  } else if (state.category) {
    lines.push(`Category: ${state.category}`);
  }
  lines.push(`Material: ${state.material}`);
  lines.push(`Strength: ${state.strength}`);
  const addonList = [];
  if (state.addons.priming) addonList.push("Priming");
  if (state.addons.paint === "flat") addonList.push("Paint (Flat)");
  if (state.addons.paint === "simple") addonList.push("Paint (Simple)");
  if (state.addons.paint === "detailed") addonList.push("Paint (Detailed)");
  if (state.addons.rush) addonList.push("Rush delivery");
  if (addonList.length) lines.push(`Add-ons: ${addonList.join(", ")}`);
  lines.push(`Estimated total: ${currency(price.total)}`);
  if (agreed) lines.push("Agreed to the Refund & Reprint Policy and Terms & Conditions: Yes");
  return lines.join("\n");
}

